  "head": "befe832957da3f58ae0bb6a7eb7f8d925d94c532",
  "route": "node-host system.run -> exec authorization -> process runner",
  "staticAssignment": {
    "result": {
      "ok": true,
      "payload": {
        "exitCode": 0,
        "timedOut": false,
        "success": true,
        "stdout": "static-ok\n",
        "stderr": "",
        "error": null
      }
    },
    "processLaunches": 1
  },
  "recursiveScalarAssignment": {
    "result": {
      "ok": false,
      "error": {
        "code": "SYSTEM_RUN_DENIED",
        "message": "SYSTEM_RUN_DENIED: approval required"
      }
    },
    "processLaunches": 0,
    "markerExists": false
  },
  "recursiveKeyedAssignment": {
    "result": {
      "ok": false,
      "error": {
        "code": "SYSTEM_RUN_DENIED",
        "message": "SYSTEM_RUN_DENIED: approval required"
      }
    },
    "processLaunches": 0,
    "markerExists": false
  },
  "recursiveKeyedAppendAssignment": {
    "result": {
      "ok": false,
      "error": {
        "code": "SYSTEM_RUN_DENIED",
        "message": "SYSTEM_RUN_DENIED: approval required"
      }
    },
    "processLaunches": 0,
    "markerExists": false
  }
}
```

The proof used synthetic configuration, isolated state, loopback-only execution, and no live external Gateway, channel, or model.
